@Component("endorsement-handler")
@ProcessingGroup("endorsement-processing-group")
public class EndorsementEventHandler {
	
	// core constructor
	EndorsementEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateEndorsementEvent
     */
    @EventHandler
    public void handle( CreateEndorsementEvent event) {
        entityManager.persist(new Endorsement(event.getEndorsementId(), event.getEndorsementNumber(), event.getEffectiveDate(), event.getDescription(), event.getPolicy()));
    }

    /*
     * @param	event UpdateEndorsementEvent
     */
    @EventHandler
    public Endorsement handle( UpdateEndorsementEvent event) {
    	entityManager.merge(new Endorsement(event.getEndorsementId(), event.getEndorsementNumber(), event.getEffectiveDate(), event.getDescription(), event.getPolicy()));
    }
    
    /*
     * @param	event DeleteEndorsementEvent
     */
    @EventHandler
    public void on( DeleteEndorsementEvent event) {
    	Endorsement entity = new Endorsement();
   
    	// ------------------------------------------
    	// apply the EndorsementId
    	// ------------------------------------------
    	entity.setEndorsementId( event.getEndorsementId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final EndorsementRepository endorsementEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(EndorsementEventHandler.class.getName());

}
